# ---------------------------------------------------------------- docs pack
def docs_pack():
    groups = [
        ('gov', 'الحوكمة', [('استراتيجية الأمن السيبراني', '1-1'), ('قرار الإدارة وميثاق اللجنة', '1-2'), ('الأدوار والمسؤوليات', '1-4'),
                            ('منهجية إدارة المخاطر', '1-5'), ('الأمن في المشاريع والتغيير', '1-6'), ('سجل الالتزامات', '1-7'),
                            ('خطة المراجعة والتدقيق', '1-8'), ('أمن الموارد البشرية', '1-9'), ('برنامج التوعية والتدريب', '1-10')]),
        ('def', 'التعزيز (1)', [('الأصول والاستخدام المقبول والتصنيف', '2-1'), ('الهويات والصلاحيات', '2-2'), ('حماية الأنظمة ومعايير التقوية', '2-3'),
                                ('البريد الإلكتروني', '2-4'), ('أمن الشبكات', '2-5'), ('الأجهزة المحمولة', '2-6'), ('حماية البيانات والتشفير', '2-7 و2-8')]),
        ('res', 'التعزيز (2) والصمود والأطراف', [('النسخ الاحتياطية', '2-9'), ('الثغرات واختبار الاختراق', '2-10 و2-11'), ('السجلات والمراقبة', '2-12'),
                                                ('الحوادث والتهديدات', '2-13'), ('الأمن المادي وتطبيقات الويب', '2-14 و2-15'), ('الاستمرارية والتعافي', '3-1'),
                                                ('الأطراف الخارجية والسحابة', '4-1 و4-2')]),
    ]
    cols = []
    for comp, name, docs in groups:
        main, tint, light = C[comp]
        rows = ''.join(f'<div style="display:flex;flex-direction:row-reverse;align-items:baseline;gap:12px;border-top:1px solid {LINE};padding:6px 0">'
                       f'<p style="flex:1;font-size:24px;line-height:1.35;color:{TEXT}">{t(d)}</p>'
                       f'<p style="font-family:{M};font-size:24px;font-weight:600;line-height:1.35;color:{main}">{t(c)}</p></div>' for d, c in docs)
        cols.append(f'<div style="flex:1;display:flex;flex-direction:column;gap:0;background:{CARD};border:1px solid {LINE};border-top:6px solid {main};border-radius:16px;padding:22px 26px">'
                    f'<h3 style="font-family:{H};font-size:28px;font-weight:700;line-height:1.35;color:{main};padding-bottom:10px">{t(name)}</h3>{rows}</div>')
    h = f'<div style="display:flex;flex-direction:row-reverse;gap:28px;align-items:flex-start">{"".join(cols)}</div>'
    est = 51 + 38 + 10 + 9 * 46  # card padding+border, heading, its padding, 9 rows
    main = C[CO][0]
    ps = ''.join(f'<p style="font-size:24px;line-height:1.4;color:{TEXT};background:{CARD};border:1px solid {LINE};padding:8px 20px;border-radius:40px">{t(x)}</p>'
                 for x in ['مالك واضح', 'رقم إصدار', 'موعد مراجعة', 'اعتماد صاحب الصلاحية (1-3-1)', 'تعميم على المعنيين'])
    ch = (f'<div style="display:flex;flex-direction:row-reverse;flex-wrap:wrap;align-items:center;gap:14px">'
          f'<p style="font-size:24px;font-weight:700;line-height:1.4;color:{main}">{t("كل وثيقة في الحزمة لها:")}</p>{ps}</div>')
    return h + spacer() + ch, est + 36 + 52

