# ---------------------------------------------------------------- review calendar
def calendar():
    colsd = [
        ('شهرياً', CO, ['تقارير الثغرات والتحديثات', 'مؤشرات المراقبة والتنبيهات', 'تحديث الأدلة التشغيلية', 'مطابقة الحماية مع سجل الأصول']),
        ('ربع سنوي', CO, ['مراجعة صلاحيات الأنظمة الحساسة', 'تقرير للجنة الإشرافية', 'اختبار استعادة لعينة', 'محاكاة تصيد']),
        ('نصف سنوي', CO, ['مراجعة قواعد الجدار الناري', 'تمرين استجابة للحوادث', 'مراجعة الحسابات المميزة']),
        ('سنوياً', CO, ['مراجعات X-4 ومراجعة الوثائق', 'التقييم الذاتي الشامل', 'المراجعة المستقلة', 'اختبار الاختراق', 'اختبار التعافي من الكوارث']),
        ('عند الحدث', 'gov', ['مشروع أو تغيير جوهري', 'عقد أو خدمة جديدة', 'حادثة كبيرة', 'تنظيم أو إصدار جديد', 'تغيير تنظيمي في الجهة']),
    ]
    out = []
    ests = []
    w = (1664 - 4 * 20) / 5 - 44
    for name, comp, items in colsd:
        main, tint, light = C[comp]
        its = ''.join(f'<div style="display:flex;flex-direction:row-reverse;align-items:flex-start;gap:10px">'
                      f'<div style="height:34px;display:flex;align-items:center"><div style="width:10px;min-width:10px;height:10px;border-radius:50%;background:{main}"></div></div>'
                      f'<p style="flex:1;font-size:24px;line-height:1.4;color:{TEXT}">{t(x)}</p></div>' for x in items)
        out.append(f'<div style="flex:1;display:flex;flex-direction:column;gap:12px;background:{CARD};border:1px solid {LINE};border-radius:16px;overflow:hidden">'
                   f'<div style="background:{main};padding:14px 22px"><h3 style="font-family:{H};font-size:28px;font-weight:700;line-height:1.3;color:{ON}">{t(name)}</h3></div>'
                   f'<div style="display:flex;flex-direction:column;gap:12px;padding:6px 22px 22px">{its}</div></div>')
        ests.append(64 + 12 + 6 + 22 + sum(th(x, 24, w - 20, 1.4) + 12 for x in items))
    return f'<div style="display:flex;flex-direction:row-reverse;gap:20px;align-items:stretch">{"".join(out)}</div>', max(ests)

