def m_kpi():
    t_, e = mocks.mtable(['المؤشر', 'القيمة في 2026-09-30', 'الهدف الداخلي', 'حالة الهدف', 'اكتمال المتطلب', 'الفجوة أو الخطر المتبقي'],
        [list(r) for r in KPI], [21, 18, 11, 12, 14, 24], status_col=(3, 4))
