# ---------------------------------------------------------------- readiness
def readiness():
    before = ['سجل أدلة محدث لكل ضابط، بأدلة ضمن فترة التقييم', 'تقييم ذاتي حديث بأداة الهيئة، وخطط معالجة لفجواته', 'مبرر موثق ومعتمد لكل ضابط «غير منطبق»',
              'منسق رئيسي، ومسؤول لكل مكون فرعي', 'عرض موجز: الهيكل والنطاق والإنجازات والفجوات']
    during = ['قدّم الدليل المطلوب بالضبط، لا ملفات غير مطلوبة', 'اعرض الأنظمة مباشرة عند الطلب، لا لقطات قديمة', 'كن صريحاً في الفجوات، واعرض خطة معالجتها',
              'دوّن كل طلب وموعده، وتابعه حتى الإغلاق', 'بعده: خطة تصحيحية تُعرض على اللجنة (1-8-3)']
    out = []
    ests = []
    for name, icon, items in (('قبل التقييم', 'Clock', before), ('أثناء التقييم وبعده', 'Users', during)):
        b, e = bullets(items, 26, CO, width=760, gap=14, mark='check')
        out.append(f'<div style="flex:1;display:flex;flex-direction:column;gap:20px;background:{CARD};border:1px solid {LINE};border-radius:20px;padding:30px 32px">'
                   f'<div style="display:flex;flex-direction:row-reverse;align-items:center;gap:18px">{icon_chip(icon, CO, 56)}'
                   f'<h3 style="font-family:{H};font-size:32px;font-weight:700;line-height:1.35;color:{TEXT}">{t(name)}</h3></div>{b}</div>')
        ests.append(60 + 56 + 20 + e)
    return f'<div style="display:flex;flex-direction:row-reverse;gap:32px">{"".join(out)}</div>', max(ests)

